const http2 = require('http2');
const fs = require('fs');
const jwt = require('jsonwebtoken');
const { FinancialLedger } = require('../models/finance');

const server = http2.createSecureServer({
  key: fs.readFileSync('/etc/ssl/server.key'),
  cert: fs.readFileSync('/etc/ssl/server.crt')
});

server.on('stream', async (stream, headers) => {
  const reqPath = headers[':path'];
  const url = new URL(reqPath, 'https://analytics.fintech.internal');

  if (url.pathname === '/dashboard') {
    const companyId = url.searchParams.get('companyId');

    // Authenticate and authorize session prior to initiating HTTP/2 server push
    const authHeader = headers['authorization'];
    if (!authHeader) {
      stream.respond({ ':status': 401 });
      return stream.end(JSON.stringify({ error: 'Authentication required' }));
    }

    let user;
    try {
      user = jwt.verify(authHeader.replace('Bearer ', ''), process.env.JWT_SECRET);
    } catch {
      stream.respond({ ':status': 401 });
      return stream.end(JSON.stringify({ error: 'Invalid token' }));
    }

    // Push resource only if client belongs to the requested company
    if (companyId && stream.pushAllowed) {
      if (user.companyId !== companyId) {
        stream.respond({ ':status': 403 });
        return stream.end(JSON.stringify({ error: 'Access denied: company mismatch' }));
      }

      stream.pushStream({ ':path': `/api/balance-sheets/${companyId}` }, async (err, pushStream) => {
        if (err) return;
        const ledger = await FinancialLedger.findOne({ where: { companyId } });
        pushStream.respond({
          ':status': 200,
          'content-type': 'application/json'
        });
        pushStream.end(JSON.stringify(ledger));
      });
    }

    stream.respond({ ':status': 200, 'content-type': 'text/html' });
    stream.end('<html><body>Dashboard loaded</body></html>');
  }
});

server.listen(8443);
